    """The (color, top, left) of every size x size solid single-color square."""
    h, w = len(grid), len(grid[0])
    return [(grid[i][j], i, j) for i in range(h - size + 1) for j in range(w - size + 1)
            if grid[i][j] and all(grid[i + a][j + b] == grid[i][j] for a in range(size) for b in range(size))]

def paint_lines(grid, lines):
    """Paint cells from a {(i, j): color} map; cells claimed by two different colors become 0."""
    for (i, j), cs in lines.items():
        grid[i][j] = next(iter(cs)) if len(cs) == 1 else 0
    return grid

def block_cross_lines(grid):
    """Every solid 3x3 block paints its full center row and center column; crossings of different blocks\' lines are 0."""
    line = {}
    for c, R, C in solid_blocks(grid):
        for j in range(len(grid[0])): line.setdefault((R, j), set()).add(c)
        for i in range(len(grid)): line.setdefault((i, C), set()).add(c)
    return line
